",\n    \"echarts\": \"6.1.0\",\n    \"html-to-image\": \"^1.11.13\",\n    \"json5\": \"^2.2.3\",\n    \"katex\": \"^0.16\",\n    \"lucide-react\": \"^0.553.0\",\n    \"marked\": \"16.4.1\",\n    \"marked-katex-extension\": \"^4\",\n    \"mermaid\": \"11.12.2\",\n    \"mermaid-legacy\": \"npm:mermaid@9.2.2\",\n    \"onml\": \"^2.1.0\",\n    \"preact\": \"10.27.3\",\n    \"react\": \"^19.1.0\",\n    \"react-dom\": \"^19.1.0\",\n    \"tailwind-merge\": \"^3.3.1\",\n    \"temml\": \"^0.13.1\",\n    \"wavedrom\": \"3.6.2\",\n    \"webextension-polyfill\": \"^0.12.0\"\n  },\n  \"devDependencies\": {\n    \"@crxjs/vite-plugin\": \"2.2.1\",\n    \"@nolebase/vitepress-plugin-git-changelog\": \"^2.18.2\",\n    \"@tailwindcss/vite\": \"^4.1.15\",\n    \"@types/chrome\": \"^0.1.24\",\n    \"@types/jsdom\": \"^27.0.0\",\n    \"@types/jszip\": \"^3.4.1\",\n    \"@types/node\": \"^24.9.0\",\n    \"@types/react\": \"^19.2.2\",\n    \"@types/react-dom\": \"^19.2.2\",\n    \"@types/webextension-polyfill\": \"^0.12.3\",\n    \"@vitejs/plugin-react\": \"5.1.0\",\n    \"@vitest/coverage-v8\": \"^5.0.3\",\n    \"@vitest/ui\": \"^5.0.3\",\n    \"chrome-webstore-upload-cli\": \"3.5.0\",\n    \"esbuild\": \"0.25.11\",\n    \"fs-extra\": \"^11.3.0\",\n    \"jsdom\": \"^27.1.0\",\n    \"jszip\": \"^3.10.1\",\n    \"nodemon\": \"^3.1.10\",\n    \"oxfmt\": \"^0.65.0\",\n    \"oxlint\": \"^1.80.0\",\n    \"tailwindcss\": \"^4.1.15\",\n    \"ts-node\": \"^10.9.2\",\n    \"typescript\": \"^5.8.3\",\n    \"vite\": \"^7.1.11\",\n    \"vite-tsconfig-paths\": \"^5.1.4\",\n    \"vitepress\": \"^1.6.4\",\n    \"vitest\": \"^5.0.3\",\n    \"vue\": \"^3.5.24\",\n    \"vue3-marquee\": \"^4.2.2\",\n    \"web-ext\": \"10.5.0\",\n    \"web-ext-run\": \"^0.2.4\"\n  },\n  \"overrides\": {\n    \"rollup\": \"^4.24.0\"\n  }\n}\n"
