      "path": "src/pages/background/siteAccessRegistration.ts",
      "content": "import browser from 'webextension-polyfill';\n\nimport { logger } from '@/core/services/LoggerService';\nimport { isFirefox } from '@/core/utils/browser';\nimport {\n  customWebsiteOriginPatterns,\n  customWebsitesIncludeHost,\n  sanitizeCustomWebsites,\n} from '@/core/utils/customWebsites';\nimport { isChatGptProUsageSupported } from '@/features/plugins/builtin/chatgptProUsage/manifest';\nimport {\n  partitionPluginOriginPatterns,\n  pluginsToOriginPatterns,\n} from '@/features/plugins/runtime/siteRegistration';\nimport { matchesAnyPattern } from '@/features/plugins/sites/matchPattern';\nimport { listPluginManifests } from '@/features/plugins/sources/defaultSources';\nimport type { PluginManifest } from '@/features/plugins/types';\n\nimport {\n  BRIDGE_ACCOUNT_MAIN_SCRIPT_ID,\n  isBridgeAccountObserverSupported,\n  syncBridgeAccountObserver,\n} from './bridge/accountObserverRegistration';\nimport {\n  CHATGPT_PRO_USAGE_MAIN_SCRIPT_ID,\n  syncChatGptProUsageObserver,\n} from './chatgptProUsageRegistration';\nimport { unregisterRegisteredContentScripts } from './contentScriptRegistration';\nimport { loadEnabledPlugins } from './enabledPlugins';\nimport { createPromptNudgeRegistration } from './promptNudgeRegistration';\nimport { syncShadowKeyGuardRegistration } from './shadowKeyGuardRegistration';\nimport { includeGrantedSites } from './siteGrantSyncScope';\n\nconst CUSTOM_CONTENT_SCRIPT_ID = 'gv-custom-content-script';\nconst PLUGIN_CONTENT_SCRIPT_ID = 'gv-plugin-content-script';\nconst PLUGIN_EMBEDDED_CONTENT_SCRIPT_ID = 'gv-plugin-embedded-content-script';\nconst CLAUDE_USAGE_MAIN_SCRIPT_ID = 'gv-plugin-claude-usage-main';\nconst CUSTOM_WEBSITE_KEY = 'gvPromptCustomWebsites';\nconst LOOPBACK_HOSTS = new Set(['127.0.0.1', 'localhost', '[::1]']);\n\n/** Whether the list has an entry for `host` already: the host on any port, or a parent domain. */\nfunction hasEntryForHost(entries: readonly unknown[], host: string): boolean {\n  return (\n    customWebsitesIncludeHost(entries, host) ||\n    sanitizeCustomWebsites(entries).some((entry) => entry.replace(/:\\d+$/, '') === host)\n  );\n}\n\nexport function createSiteAccessRegistration() {\n  const MANIFEST_DEFAULT_DOMAINS = new Set(\n    [\n      ...(chrome.runtime.getManifest().host_permissions || []),\n      ...(chrome.runtime.getManifest().content_scripts?.flatMap((c) => c.matches || []) || []),\n    ]\n      .map(patternToDomain)\n      .filter((d): d is string => !!d),\n  );\n\n  // Domains targeted by plugins. Granting one of these (when a user\n  // enables a plugin) must NOT also register it as a Prompt-Manager \"custom\n  // website\", so we exclude them from the permissions.onAdded → custom-website\n  // merge below. Populated asynchronously from the cached catalog (see\n  // refreshPluginSiteDomains).\n  let pluginSiteDomains = new Set<string>();\n\n  async function loadPluginCatalog(): Promise<readonly PluginManifest[]> {\n    try {\n      return await listPluginManifests();\n    } catch {\n      return [];\n    }\n  }\n\n  async function refreshPluginSiteDomains(): Promise<void> {\n    const catalog = await loadPluginCatalog();\n    pluginSiteDomains = new Set(\n      pluginsToOriginPatterns(catalog)\n        .map(patternToDomain)\n        .filter((d): d is string => !!d),\n    );\n  }\n\n  function patternToDomain(pattern: string | undefined): string | null {\n    if (!pattern) return null;\n    try {\n      const withoutScheme = pattern.replace(/^[^:]+:\\/\\//, '');\n      const hostPart = withoutScheme.replace(/\\/.*$/, '').replace(/^\\*\\./, '');\n      if (!hostPart || hostPart === '*') return null;\n      return hostPart;\n    } catch {\n      return null;\n    }\n  }\n\n  function toMatchPatterns(domain: string): string[] {\n    return customWebsiteOriginPatterns(domain) ?? [];\n  }\n\n  function toRelativeExtensionPath(resource: string): string {\n    try {\n      const url = new URL(resource);\n      if (url.protocol === 'moz-extension:') {\n        return url.pathname.replace(/^\\/+/, '');\n      }\n    } catch {\n      // Not an absolute extension URL; fall through.\n    }\n\n    return resource.replace(/^\\/+/, '');\n  }\n\n  function extractDomainsFromOrigins(origins?: string[]): string[] {\n    if (!Array.isArray(origins)) return [];\n    const domains = origins\n      .map(patternToDomain)\n      .filter((d): d is string => !!d)\n      // The Local Bridge pairing grants http://127.0.0.1/*; loopback is never a prompt site.\n      .filter((d) => !LOOPBACK_HOSTS.has(d))\n      .filter((d) => !MANIFEST_DEFAULT_DOMAINS.has(d))\n      .filter((d) => !pluginSiteDomains.has(d));\n    return Array.from(new Set(domains));\n  }\n\n  async function filterGrantedOrigins(patterns: string[]): Promise<string[]> {\n    const granted: string[] = [];\n\n    for (const origin of patterns) {\n      try {\n        const hasPermission = await browser.permissions.contains({ origins: [origin] });\n        if (hasPermission) {\n          granted.push(origin);\n        }\n      } catch (error) {\n        console.warn('[Background] Failed to check permission for', origin, error);\n      }\n    }\n\n    return granted;\n  }\n\n  // Serialized for the same reason as the plugin sync below: storage and\n  // permission listeners can both fire at once and double-inject.\n  let customContentScriptSyncQueue: Promise<void> = Promise.resolve();\n\n  function syncCustomContentScripts(domains?: string[]): Promise<void> {\n    const next = customContentScriptSyncQueue.then(() => doSyncCustomContentScripts(domains));\n    customContentScriptSyncQueue = next.catch(() => {});\n    return next;\n  }\n\n  async function doSyncCustomContentScripts(domains?: string[]): Promise<void> {\n    if (!chrome.scripting?.registerContentScripts) return;\n\n    const manifestContentScript = chrome.runtime.getManifest().content_scripts?.[0];\n    if (!manifestContentScript) return;\n\n    const domainList =\n      domains ??\n      (\n        await chrome.storage.sync.get({\n          [CUSTOM_WEBSITE_KEY]: [],\n        })\n      )[CUSTOM_WEBSITE_KEY];\n\n    const matchPatterns = Array.from(\n      new Set(\n        (Array.isArray(domainList) ? domainList : []).flatMap(toMatchPatterns).filter(Boolean),\n      ),\n    );\n\n    const grantedMatches = await filterGrantedOrigins(matchPatterns);\n\n    try {\n      await chrome.scripting.unregisterContentScripts({ ids: [CUSTOM_CONTENT_SCRIPT_ID] });\n    } catch {\n      // No-op if script was not registered\n    }\n\n    if (!grantedMatches.length) return;\n\n    const runAt =\n      manifestContentScript.run_at === 'document_start'\n        ? 'document_start'\n        : manifestContentScript.run_at === 'document_end'\n          ? 'document_end'\n          : 'document_idle';\n\n    const jsResources = isFirefox()\n      ? (manifestContentScript.js || []).map(toRelativeExtensionPath)\n      : manifestContentScript.js || [];\n    const cssResources = isFirefox()\n      ? manifestContentScript.css?.map(toRelativeExtensionPath)\n      : manifestContentScript.css;\n\n    try {\n      await chrome.scripting.registerContentScripts([\n        {\n          id: CUSTOM_CONTENT_SCRIPT_ID,\n          js: jsResources,\n          css: cssResources,\n          matches: grantedMatches,\n          allFrames: manifestContentScript.all_frames,\n          runAt,\n          persistAcrossSessions: true,\n        },\n      ]);\n      logger.info('[Background] Custom content scripts registered', { matches: grantedMatches });\n    } catch (error) {\n      console.error('[Background] Failed to register custom content scripts:', error);\n    }\n\n    // Registration only covers future navigations, so enabling a site would\n    // otherwise take a reload to show up. Cover the tabs already open on it.\n    await injectVoyagerScriptIntoOpenTabs(grantedMatches, undefined, jsResources, cssResources);\n  }\n\n  /**\n   * A live Voyager content script answers this ping. Orphaned scripts (extension\n   * updated/reloaded underneath the page) have an invalidated runtime and cannot\n   * respond, so they correctly read as \"not injected\".\n   */\n  async function hasLiveVoyagerContentScript(tabId: number, frameId?: number): Promise<boolean> {\n    try {\n      const message = { type: 'gv.content.ping' };\n      const response = (\n        frameId === undefined\n          ? await browser.tabs.sendMessage(tabId, message)\n          : await browser.tabs.sendMessage(tabId, message, { frameId })\n      ) as { ok?: boolean } | undefined;\n      return response?.ok === true;\n    } catch {\n      return false;\n    }\n  }\n\n  async function getMatchingFrameIds(tabId: number, matches: readonly string[]): Promise<number[]> {\n    try {\n      const frames = await chrome.scripting.executeScript({\n        target: { tabId, allFrames: true },\n        func: () => location.href,\n      });\n      return frames.flatMap((frame) =>\n        typeof frame.result === 'string' && matchesAnyPattern(frame.result, matches)\n          ? [frame.frameId]\n          : [],\n      );\n    } catch {\n      // Never substitute the parent frame for an unresolvable companion frame.\n      // The persistent registration will cover it on the next navigation/reload.\n      return [];\n    }\n  }\n\n  async function injectVoyagerScriptIntoOpenTabs(\n    tabMatches: string[],\n    frameMatches: string[] | undefined,\n    jsResources: string[],\n    cssResources: string[] | undefined,\n  ): Promise<void> {\n    if (!chrome.scripting?.executeScript || !tabMatches.length) return;\n    let tabs: chrome.tabs.Tab[] = [];\n    try {\n      tabs = await chrome.tabs.query({ url: tabMatches });\n    } catch {\n      return;\n    }\n    for (const tab of tabs) {\n      if (typeof tab.id !== 'number') continue;\n      try {\n        const frameIds = frameMatches ? await getMatchingFrameIds(tab.id, frameMatches) : [0];\n        const missingFrameIds: number[] = [];\n        for (const frameId of frameIds) {\n          // insertCSS APPENDS a fresh copy on every call. Check every matching\n          // frame independently so an already-live Claude parent does not prevent\n          // first-time injection into its artifact child frame.\n          if (!(await hasLiveVoyagerContentScript(tab.id, frameId))) missingFrameIds.push(frameId);\n        }\n        if (!missingFrameIds.length) continue;\n        const target = { tabId: tab.id, frameIds: missingFrameIds };\n        if (cssResources?.length) {\n          await chrome.scripting.insertCSS({ target, files: cssResources });\n        }\n        if (jsResources.length) {\n          await chrome.scripting.executeScript({ target, files: jsResources });\n        }\n      } catch {\n        // Tab may be discarded or disallow injection — ignore; reload will cover it.\n      }\n    }\n  }\n\n  // Serialized: concurrent syncs (storage listener + permission events) would\n  // otherwise race the ping-then-inject sequence and double-inject.\n  let pluginContentScriptSyncQueue: Promise<void> = Promise.resolve();\n\n  function syncPluginContentScripts(): Promise<void> {\n    const next = pluginContentScriptSyncQueue.then(() => doSyncPluginContentScripts());\n    pluginContentScriptSyncQueue = next.catch(() => {});\n    return next;\n  }\n\n  /**\n   * Plugin ecosystem — dynamic content-script registration.\n   *\n   * Mirrors syncCustomContentScripts: derive the origins of currently-ENABLED\n   * plugins, keep only those the user has already granted host permission\n   * for, and (re)register the content script for them. The content script runs\n   * `startPluginHost()`, which mounts the enabled plugin on the page.\n   *\n   * Plugin enable-state is the single source of truth (storage.local); permissions\n   * and registrations are derived from it.\n   */\n  async function doSyncPluginContentScripts(): Promise<void> {\n    if (!chrome.scripting?.registerContentScripts) return;\n\n    const enabledPlugins = await loadEnabledPlugins(loadPluginCatalog);\n    // Own registration call and failure path: the guard never blocks the plugin host.\n    await syncShadowKeyGuardRegistration({\n      scripting: chrome.scripting,\n      manifest: chrome.runtime.getManifest(),\n      enabledPlugins,\n      filterGranted: filterGrantedOrigins,\n      toResource: isFirefox() ? toRelativeExtensionPath : (path) => path,\n    });\n\n    const manifestContentScript = chrome.runtime.getManifest().content_scripts?.[0];\n    if (!manifestContentScript) return;\n\n    const grantedMatches = await filterGrantedOrigins(pluginsToOriginPatterns(enabledPlugins));\n\n    await unregisterRegisteredContentScripts(chrome.scripting, [\n      PLUGIN_CONTENT_SCRIPT_ID,\n      PLUGIN_EMBEDDED_CONTENT_SCRIPT_ID,\n      CLAUDE_USAGE_MAIN_SCRIPT_ID,\n      CHATGPT_PRO_USAGE_MAIN_SCRIPT_ID,\n      BRIDGE_ACCOUNT_MAIN_SCRIPT_ID,\n    ]);\n\n    if (!grantedMatches.length) return;\n\n    // Before the content scripts below, so a page loading now gets the observer at document_start.\n    await syncChatGptProUsageObserver({\n      scripting: chrome.scripting,\n      enabledPlugins,\n      grantedOrigins: grantedMatches,\n      supportsMainWorld: isChatGptProUsageSupported(),\n      queryTabs: (url) => chrome.tabs.query({ url }),\n    });\n    await syncBridgeAccountObserver({\n      scripting: chrome.scripting,\n      enabledPlugins,\n      grantedOrigins: grantedMatches,\n      supportsMainWorld: isBridgeAccountObserverSupported(),\n      queryTabs: (url) => chrome.tabs.query({ url }),\n    });\n\n    const runAt =\n      manifestContentScript.run_at === 'document_start'\n        ? 'document_start'\n        : manifestContentScript.run_at === 'document_end'\n          ? 'document_end'\n          : 'document_idle';\n\n    const jsResources = isFirefox()\n      ? (manifestContentScript.js || []).map(toRelativeExtensionPath)\n      : manifestContentScript.js || [];\n    const cssResources = isFirefox()\n      ? manifestContentScript.css?.map(toRelativeExtensionPath)\n      : manifestContentScript.css;\n    const { topFrameOrigins, embeddedFrameOrigins } = partitionPluginOriginPatterns(grantedMatches);\n\n    try {\n      const registrations: chrome.scripting.RegisteredContentScript[] = [];\n      if (topFrameOrigins.length) {\n        registrations.push({\n          id: PLUGIN_CONTENT_SCRIPT_ID,\n          js: jsResources,\n          css: cssResources,\n          matches: topFrameOrigins,\n          allFrames: false,\n          runAt,\n          persistAcrossSessions: true,\n        });\n      }\n      if (embeddedFrameOrigins.length) {\n        registrations.push({\n          id: PLUGIN_EMBEDDED_CONTENT_SCRIPT_ID,\n          js: jsResources,\n          css: cssResources,\n          matches: embeddedFrameOrigins,\n          allFrames: true,\n          runAt,\n          persistAcrossSessions: true,\n        });\n      }\n      if (registrations.length) {\n        await chrome.scripting.registerContentScripts(registrations);\n      }\n      // Inject into already-open matching tabs so the user sees the effect without\n      // a manual reload.\n      await injectVoyagerScriptIntoOpenTabs(topFrameOrigins, undefined, jsResources, cssResources);\n      if (embeddedFrameOrigins.length) {\n        await injectVoyagerScriptIntoOpenTabs(\n          grantedMatches,\n          embeddedFrameOrigins,\n          jsResources,\n          cssResources,\n        );\n      }\n    } catch (error) {\n      console.error('[Background] Failed to register plugin content scripts:', error);\n    }\n  }\n\n  const { sync: syncPromptNudgeIcon } = createPromptNudgeRegistration(() => pluginSiteDomains);\n\n  async function permissionAdded(origins?: string[]): Promise<void> {\n    // Refresh the plugin-site set FIRST so a freshly-granted plugin origin\n    // (e.g. claude.ai / chatgpt.com) is reliably excluded from the Prompt-Manager\n    // custom-website list. Otherwise onAdded can fire before the initial async\n    // refresh has populated `pluginSiteDomains`, racing a plugin site into the\n    // custom-website list.\n    await refreshPluginSiteDomains();\n\n    const domains = extractDomainsFromOrigins(origins);\n    if (domains.length) {\n      try {\n        const current = await browser.storage.sync.get({ [CUSTOM_WEBSITE_KEY]: [] });\n        const existing = Array.isArray(current[CUSTOM_WEBSITE_KEY])\n          ? current[CUSTOM_WEBSITE_KEY]\n          : [];\n        // A grant never repeats or widens an entry for its host: `example.org:3000`\n        // keeps its port, and a parent domain already covers a subdomain. The\n        // popup saves what it adds back before the browser answers, so an entry\n        // it is restoring is already here.\n        const merged = [...existing];\n        for (const domain of domains) {\n          if (!hasEntryForHost(merged, domain)) merged.push(domain);\n        }\n        if (merged.length !== existing.length) {\n          await browser.storage.sync.set({ [CUSTOM_WEBSITE_KEY]: merged });\n        }\n      } catch (error) {\n        console.warn('[Background] Failed to persist domains from permissions.onAdded:', error);\n      }\n    }\n\n    // A supported site joins cloud sync here too, when the page that asked has closed.\n    await includeGrantedSites(origins);\n\n    // A granted origin may belong to an enabled plugin — (re)register both the\n    // custom-website and the plugin content scripts for newly-granted origins.\n    await syncCustomContentScripts();\n    await syncPluginContentScripts();\n    // The freshly-granted site is now enabled, so it should no longer be nudged.\n    await syncPromptNudgeIcon();\n  }\n\n  function permissionRemoved(): void {\n    void syncCustomContentScripts();\n    // Keep plugin content-script registrations in sync when a site's host\n    // permission is revoked from the browser UI — filterGrantedOrigins will now\n    // drop the revoked origin, so the stale plugin registration is removed.\n    void syncPluginContentScripts();\n    // A revoked plugin site becomes eligible for the nudge dot again.\n    void syncPromptNudgeIcon();\n  }\n\n  return {\n    syncCustom: syncCustomContentScripts,\n    syncPlugins: syncPluginContentScripts,\n    refreshPluginSiteDomains,\n    syncPromptNudgeIcon,\n    permissionAdded,\n    permissionRemoved,\n  };\n}\n"
    },
    {
      "path": "src/pages/popup/hooks/useLocalPlugins.ts",
      "content": "import { useCallback, useEffect, useState } from 'react';\n\nimport {\n  type LocalPluginFile,\n  type LocalPluginImportResult,\n  MAX_LOCAL_PLUGIN_IMPORT_CHARS,\n  exportLocalPluginJson,\n  importLocalPlugin,\n  importLocalPluginFiles,\n  removeLocalPlugin,\n} from '@/features/plugins/local/localPluginImport';\nimport {\n  type LocalPluginRecord,\n  loadLocalPluginRecords,\n  subscribeLocalPlugins,\n} from '@/features/plugins/local/localPluginStore';\nimport { validateLocalManifest } from '@/features/plugins/local/validateLocalManifest';\nimport type { ManifestIssue } from '@/features/plugins/manifest/validate';\nimport type { PluginManifest } from '@/features/plugins/types';\n\n/** One stored local plugin, re-validated the way `LocalPluginSource` reads it. */\nexport interface LocalPluginEntry {\n  readonly id: string;\n  readonly record: LocalPluginRecord;\n  /** Null when the stored manifest no longer passes this build's checks. */\n  readonly manifest: PluginManifest | null;\n  readonly issues: readonly ManifestIssue[];\n}\n\nexport function toLocalPluginEntries(\n  records: Readonly<Record<string, LocalPluginRecord>>,\n): LocalPluginEntry[] {\n  return Object.entries(records)\n    .map(([id, record]): LocalPluginEntry => {\n      const result = validateLocalManifest(record.manifest, undefined, { hostPolicy: 'defer' });\n      return result.success\n        ? { id, record, manifest: result.data.manifest, issues: [] }\n        : { id, record, manifest: null, issues: result.error };\n    })\n    .sort((a, b) => a.id.localeCompare(b.id));\n}\n\n/** Pick → read: browser files become path + text, bounded before reading. */\nasync function readPickedFiles(\n  files: readonly File[],\n): Promise<LocalPluginFile[] | LocalPluginImportResult> {\n  const total = files.reduce((sum, file) => sum + file.size, 0);\n  if (total > MAX_LOCAL_PLUGIN_IMPORT_CHARS * 4) {\n    return {\n      ok: false,\n      issues: [{ path: 'file', message: `exceeds ${MAX_LOCAL_PLUGIN_IMPORT_CHARS} characters` }],\n    };\n  }\n  return Promise.all(\n    files.map(async (file) => ({\n      name: file.webkitRelativePath || file.name,\n      text: await file.text(),\n    })),\n  );\n}\n\nfunction downloadText(filename: string, text: string): void {\n  const blob = new Blob([text], { type: 'application/json;charset=utf-8' });\n  const url = URL.createObjectURL(blob);\n  const anchor = document.createElement('a');\n  anchor.href = url;\n  anchor.download = filename;\n  document.body.appendChild(anchor);\n  anchor.click();\n  setTimeout(() => {\n    anchor.remove();\n    URL.revokeObjectURL(url);\n  }, 0);\n}\n\n/** Local plugin list plus import / export / remove for the popup plugin page. */\nexport function useLocalPlugins() {\n  const [entries, setEntries] = useState<readonly LocalPluginEntry[]>([]);\n  const [result, setResult] = useState<LocalPluginImportResult | null>(null);\n  const [busy, setBusy] = useState(false);\n\n  useEffect(() => {\n    let active = true;\n    const load = (): void => {\n      void loadLocalPluginRecords().then((records) => {\n        if (active) setEntries(toLocalPluginEntries(records));\n      });\n    };\n    load();\n    const unsubscribe = subscribeLocalPlugins(load);\n    return () => {\n      active = false;\n      unsubscribe();\n    };\n  }, []);\n\n  const runImport = useCallback(\n    async (job: () => Promise<LocalPluginImportResult>): Promise<LocalPluginImportResult> => {\n      setBusy(true);\n      setResult(null);\n      let outcome: LocalPluginImportResult;\n      try {\n        outcome = await job();\n      } catch (error) {\n        outcome = {\n          ok: false,\n          issues: [\n            { path: 'file', message: error instanceof Error ? error.message : String(error) },\n          ],\n        };\n      }\n      setResult(outcome);\n      setBusy(false);\n      return outcome;\n    },\n    [],\n  );\n\n  const importFiles = useCallback(\n    (files: readonly File[]) =>\n      runImport(async () => {\n        const read = await readPickedFiles(files);\n        return Array.isArray(read) ? importLocalPluginFiles(read) : read;\n      }),\n    [runImport],\n  );\n\n  /** Pasted text is read as a single `plugin.json` with its CSS inlined. */\n  const importText = useCallback(\n    (text: string) => runImport(() => importLocalPluginFiles([{ name: 'plugin.json', text }])),\n    [runImport],\n  );\n\n  /**\n   * A manifest already read and previewed (the AI-reply flow), imported as is,\n   * and only over the install the preview was made against (`expectedInstalled`).\n   */\n  const importManifest = useCallback(\n    (raw: unknown, expectedInstalled: string | null) =>\n      runImport(() => importLocalPlugin(raw, undefined, { expectedInstalled })),\n    [runImport],\n  );\n\n  const remove = useCallback(async (id: string) => {\n    setResult(null);\n    try {\n      await removeLocalPlugin(id);\n    } catch (error) {\n      // Storage refused the read or write: nothing was removed; say so.\n      setResult({\n        ok: false,\n        issues: [{ path: id, message: error instanceof Error ? error.message : String(error) }],\n      });\n    }\n  }, []);\n\n  const exportPlugin = useCallback((entry: LocalPluginEntry) => {\n    downloadText(`${entry.id}.json`, exportLocalPluginJson(entry.record));\n  }, []);\n\n  return {\n    entries,\n    result,\n    busy,\n    importFiles,\n    importText,\n    importManifest,\n    remove,\n    exportPlugin,\n    clearResult: () => setResult(null),\n  };\n}\n\nexport type LocalPluginsController = ReturnType<typeof useLocalPlugins>;\n"
    },
    {
      "path": "src/features/plugins/runtime/primitiveLifecycle.ts",
      "content": "/**\n * The `native` op half of a mounted plugin: every primitive it invokes runs\n * under one shared `PluginScope`, settings updates apply in place when every\n * handle can absorb them, and otherwise the scope restarts (serialized) under\n * the new values. The engine entry owns the state (`PrimitiveSlot`).\n */\nimport { logger } from '@/core/services/LoggerService';\n\nimport { hasNativeParamTemplates, renderNativeParams } from '../manifest/nativeParamSettings';\nimport type { NativeOperation, PluginManifest, PluginSettings, SiteAdapter } from '../types';\nimport { getPrimitive } from '../verbs/registry';\nimport type { PluginInspection, PrimitiveHandle } from '../verbs/types';\nimport { PluginScope } from './pluginScope';\n\n/** The primitive state of one mounted plugin, held on its engine entry. */\nexport interface PrimitiveSlot {\n  readonly manifest: PluginManifest;\n  /** Current resolved settings; a queued restart for older ones activates nothing. */\n  settings: PluginSettings;\n  /** Side-effect ledger shared by the plugin's `native` op primitives. */\n  primitiveScope?: PluginScope;\n  /** Serializes settings-driven primitive restarts. */\n  primitiveRestart?: Promise<void>;\n  /** Target counters registered by primitives (health signal, plan D12). */\n  targetCounters: Array<() => number>;\n  /** Handles of successfully activated primitives (settings updates in place). */\n  primitiveHandles: PrimitiveHandle[];\n  /** Number of native ops that activated (handles may still be arriving). */\n  primitiveActivations: number;\n}\n\nexport interface PrimitiveEnv {\n  readonly doc: Document;\n  readonly adapter: SiteAdapter | null;\n  /** False once the slot's plugin was unmounted or remounted. */\n  readonly isCurrent: (slot: PrimitiveSlot) => boolean;\n  readonly inspectPlugins?: () => PluginInspection;\n}\n\nfunction nativeOps(manifest: PluginManifest): NativeOperation[] {\n  return (manifest.contributes.domOps ?? []).filter(\n    (op): op is NativeOperation => op.op === 'native',\n  );\n}\n\n/**\n * Run every `native` op of the plugin under one shared scope. An unknown\n * handler or invalid params are skipped with a warning; the status machine\n * has normally already reported them as needs-handler, so this is defence\n * in depth, never a crash.\n */\nexport function activatePrimitives(\n  entry: PrimitiveSlot,\n  settings: PluginSettings,\n  env: PrimitiveEnv,\n): void {\n  const ops = nativeOps(entry.manifest);\n  if (ops.length === 0) return;\n  const scope = new PluginScope();\n  entry.primitiveScope = scope;\n  entry.targetCounters = [];\n  entry.primitiveHandles = [];\n  entry.primitiveActivations = 0;\n  const context = {\n    doc: env.doc,\n    adapter: env.adapter,\n    pluginId: entry.manifest.id,\n    settings,\n    setTargetCounter: (count: () => number) => {\n      entry.targetCounters.push(count);\n    },\n    inspectPlugins: env.inspectPlugins,\n  };\n  for (const op of ops) {\n    const primitive = getPrimitive(op.handler);\n    if (!primitive) {\n      logger.warn('Unknown primitive', { id: entry.manifest.id, handler: op.handler });\n      continue;\n    }\n    const rendered = renderNativeParams(op.params, entry.manifest.contributes.settings, settings);\n    const params = rendered.success ? primitive.validateParams(rendered.data) : rendered;\n    if (!params.success) {\n      logger.warn('Invalid primitive params', {\n        id: entry.manifest.id,\n        handler: op.handler,\n        issues: params.error,\n      });\n      continue;\n    }\n    try {\n      const result = primitive.activate(scope, params.data, context);\n      entry.primitiveActivations += 1;\n      const adopt = (handle: void | PrimitiveHandle): void => {\n        if (handle && entry.primitiveScope === scope) entry.primitiveHandles.push(handle);\n      };\n      if (result instanceof Promise) {\n        result.then(adopt).catch((error) => {\n          logger.error('Primitive activation failed', {\n            id: entry.manifest.id,\n            handler: op.handler,\n            error: String(error),\n          });\n        });\n      } else {\n        adopt(result);\n      }\n    } catch (error) {\n      logger.error('Primitive activation failed', {\n        id: entry.manifest.id,\n        handler: op.handler,\n        error: String(error),\n      });\n    }\n  }\n}\n\n/**\n * Dispose the primitives' scope, then re-activate under the new settings\n * (serialized). Always chain: while a restart is still disposing there is no\n * scope to take, but the newer settings must still get their activation once\n * the queue drains — otherwise the stale restart bails on them and the plugin\n * ends up with no primitives at all.\n */\nexport function restartPrimitives(\n  entry: PrimitiveSlot,\n  settings: PluginSettings,\n  env: PrimitiveEnv,\n): void {\n  const previous = entry.primitiveScope;\n  entry.primitiveScope = undefined;\n  entry.primitiveRestart = (entry.primitiveRestart ?? Promise.resolve()).then(async () => {\n    if (previous) await previous.dispose();\n    if (!env.isCurrent(entry)) return;\n    if (entry.settings !== settings) return;\n    activatePrimitives(entry, settings, env);\n  });\n  // Begin teardown now: an immediate unmount cannot reach the scope held by this queue.\n  void previous?.dispose();\n}\n\nexport function updatePrimitiveSettings(\n  entry: PrimitiveSlot,\n  settings: PluginSettings,\n  env: PrimitiveEnv,\n): void {\n  if (!entry.primitiveScope) {\n    // No live scope: either the plugin has no primitives, or a restart is\n    // still disposing and these settings must queue behind it.\n    if (entry.primitiveRestart) restartPrimitives(entry, settings, env);\n    return;\n  }\n  const handles = entry.primitiveHandles;\n  const allInPlace =\n    // An updater receives settings, not new params; templates need fresh activation.\n    !nativeOps(entry.manifest).some((op) => hasNativeParamTemplates(op.params)) &&\n    handles.length === entry.primitiveActivations &&\n    handles.every((handle) => typeof handle.updateSettings === 'function');\n  if (allInPlace && handles.length > 0) {\n    for (const handle of handles) handle.updateSettings?.(settings);\n    return;\n  }\n  restartPrimitives(entry, settings, env);\n}\n"
    },
    {
      "path": "src/features/export/services/ConversationExportService.ts",
      "content": "/**\n * Conversation Export Service\n * Unified service for exporting conversations in multiple formats\n * Uses Strategy pattern for format-specific implementations\n */\nimport { IMAGE_RENDER_EVENT_ERROR_CODE, isEventLikeImageRenderError } from '../types/errors';\nimport { DEFAULT_EXPORT_SPEAKER_LABELS } from '../types/export';\nimport type {\n  ChatTurn,\n  ConversationMetadata,\n  ExportFormat,\n  ExportLayout,\n  ExportOptions,\n  ExportResult,\n} from '../types/export';\nimport { DeepResearchPDFPrintService } from './DeepResearchPDFPrintService';\nimport { ImageExportService } from './ImageExportService';\nimport { MarkdownFormatter } from './MarkdownFormatter';\nimport { PDFPrintService } from './PDFPrintService';\nimport { MAX_EXPORT_IMAGE_TOTAL_BYTES, fetchBoundedExportImage } from './boundedImageFetch';\nimport { packageMarkdownImages } from './markdownImageArchive';\n\n/**\n * Main export service\n * Coordinates different export strategies\n */\nexport class ConversationExportService {\n  private static readonly REPORT_JSON_FORMAT = 'gemini-voyager.report.v1' as const;\n\n  private static readonly CHAT_JSON_FORMAT = 'gemini-voyager.chat.v1' as const;\n\n  private static assertNotAborted(signal?: AbortSignal): void {\n    if (signal?.aborted) throw new DOMException('Export cancelled', 'AbortError');\n  }\n\n  /**\n   * Export conversation in specified format\n   */\n  static async export(\n    turns: ChatTurn[],\n    metadata: ConversationMetadata,\n    options: ExportOptions,\n  ): Promise<ExportResult> {\n    try {\n      this.assertNotAborted(options.signal);\n      const layout: ExportLayout = options.layout ?? 'conversation';\n      if (layout === 'document') {\n        return await this.exportDocument(turns, metadata, options);\n      }\n\n      const conversationOptions: ExportOptions = {\n        ...options,\n        speakerLabels: options.speakerLabels ?? DEFAULT_EXPORT_SPEAKER_LABELS,\n      };\n\n      switch (conversationOptions.format) {\n        case 'json':\n          return this.exportJSON(turns, metadata, conversationOptions);\n\n        case 'markdown':\n          return await this.exportMarkdown(turns, metadata, conversationOptions);\n\n        case 'pdf':\n          return await this.exportPDF(turns, metadata, conversationOptions);\n\n        case 'image':\n          return await this.exportImage(turns, metadata, conversationOptions);\n\n        default:\n          return {\n            success: false,\n            format: options.format,\n            error: `Unsupported format: ${options.format}`,\n          };\n      }\n    } catch (error) {\n      return {\n        success: false,\n        format: options.format,\n        error: this.normalizeError(error),\n      };\n    }\n  }\n\n  private static normalizeError(error: unknown): string {\n    if (error instanceof DOMException) {\n      return error.message;\n    }\n    if (error instanceof Error) {\n      return error.message;\n    }\n\n    if (typeof Event !== 'undefined' && error instanceof Event) {\n      return IMAGE_RENDER_EVENT_ERROR_CODE;\n    }\n\n    if (isEventLikeImageRenderError(error)) {\n      return IMAGE_RENDER_EVENT_ERROR_CODE;\n    }\n\n    return String(error);\n  }\n\n  private static async exportDocument(\n    turns: ChatTurn[],\n    metadata: ConversationMetadata,\n    options: ExportOptions,\n  ): Promise<ExportResult> {\n    const content = this.extractDocumentContent(turns);\n\n    switch (options.format) {\n      case 'json':\n        return this.exportDocumentJSON(content, metadata, options);\n      case 'markdown':\n        return await this.exportDocumentMarkdown(content, metadata, options);\n      case 'pdf':\n        return await this.exportDocumentPDF(content, metadata, options);\n      case 'image':\n        return await this.exportDocumentImage(content, metadata, options);\n      default:\n        return {\n          success: false,\n          format: options.format,\n          error: `Unsupported format: ${options.format}`,\n        };\n    }\n  }\n\n  /**\n   * Export as JSON, with the same Markdown-formatted content as the Markdown export.\n   */\n  private static exportJSON(\n    turns: ChatTurn[],\n    metadata: ConversationMetadata,\n    options: ExportOptions,\n  ): ExportResult {\n    const processedItems = turns.map((turn) => {\n      const attachments = turn.userContent\n        ? turn.userContent.attachments\n        : (turn.attachments ?? []);\n      return {\n        user: turn.userContent?.text || turn.user,\n        assistant: turn.assistantContent?.text || turn.assistant,\n        starred: turn.starred,\n        ...(attachments.length > 0 ? { attachments } : {}),\n      };\n    });\n\n    const payload = {\n      format: this.CHAT_JSON_FORMAT,\n      url: metadata.url,\n      exportedAt: metadata.exportedAt,\n      count: metadata.count,\n      title: metadata.title,\n      items: processedItems,\n    };\n\n    const filename =\n      options.filename || this.generateFilename('json', metadata.title, metadata.platform);\n    this.assertNotAborted(options.signal);\n    this.downloadJSON(payload, filename);\n\n    return {\n      success: true,\n      format: 'json' as ExportFormat,\n      filename,\n    };\n  }\n\n  /**\n   * Export as Markdown\n   */\n  private static async exportMarkdown(\n    turns: ChatTurn[],\n    metadata: ConversationMetadata,\n    options: ExportOptions,\n  ): Promise<ExportResult> {\n    // First create a clean markdown (no inlining)\n    let markdown = MarkdownFormatter.format(turns, metadata, {\n      usePromptAsTurnHeading: options.usePromptAsTurnHeading,\n      speakerLabels: options.speakerLabels,\n    });\n\n    // Strip image source attribution lines if user opted out\n    if (options.includeImageSource === false) {\n      markdown = markdown.replace(/\\n\\*Source: \\[[^\\]]*\\]\\([^)]*\\)\\*\\n/g, '\\n');\n    }\n\n    const filename =\n      options.filename || this.generateFilename('md', metadata.title, metadata.platform);\n    const archived = await this.downloadMarkdownOrZip(\n      markdown,\n      filename,\n      'chat.md',\n      options.signal,\n    );\n    return {\n      success: true,\n      format: 'markdown' as ExportFormat,\n      filename: archived.filename,\n      omittedImageCount: archived.omittedImageCount,\n    };\n  }\n\n  /**\n   * Export as PDF (using print dialog)\n   */\n  private static async exportPDF(\n    turns: ChatTurn[],\n    metadata: ConversationMetadata,\n    options: ExportOptions,\n  ): Promise<ExportResult> {\n    await PDFPrintService.export(turns, metadata, {\n      fontSize: options.fontSize,\n      speakerLabels: options.speakerLabels,\n      signal: options.signal,\n    });\n\n    // Note: We can't get the actual filename from print dialog\n    // User chooses filename in Save as PDF dialog\n    return {\n      success: true,\n      format: 'pdf' as ExportFormat,\n      filename: options.filename || this.generateFilename('pdf', metadata.title, metadata.platform),\n    };\n  }\n\n  /**\n   * Export as image (PNG)\n   */\n  private static async exportImage(\n    turns: ChatTurn[],\n    metadata: ConversationMetadata,\n    options: ExportOptions,\n  ): Promise<ExportResult> {\n    const filename =\n      options.filename || this.generateFilename('png', metadata.title, metadata.platform);\n    await ImageExportService.export(turns, metadata, {\n      filename,\n      fontSize: options.fontSize,\n      imageWidth: options.imageWidth,\n      speakerLabels: options.speakerLabels,\n      signal: options.signal,\n    });\n    return { success: true, format: 'image' as ExportFormat, filename };\n  }\n\n  private static exportDocumentJSON(\n    content: { markdown: string; html: string },\n    metadata: ConversationMetadata,\n    options: ExportOptions,\n  ): ExportResult {\n    const payload = {\n      format: this.REPORT_JSON_FORMAT,\n      url: metadata.url,\n      exportedAt: metadata.exportedAt,\n      title: metadata.title,\n      content: {\n        markdown: content.markdown,\n        html: content.html,\n      },\n    };\n\n    const filename =\n      options.filename || this.generateFilename('json', metadata.title, metadata.platform);\n    this.assertNotAborted(options.signal);\n    this.downloadJSON(payload, filename);\n    return {\n      success: true,\n      format: 'json' as ExportFormat,\n      filename,\n    };\n  }\n\n  private static async exportDocumentMarkdown(\n    content: { markdown: string; html: string },\n    metadata: ConversationMetadata,\n    options: ExportOptions,\n  ): Promise<ExportResult> {\n    const markdown = this.composeDocumentMarkdown(content.markdown, metadata);\n    const filename =\n      options.filename || this.generateFilename('md', metadata.title, metadata.platform);\n    const mdEntryName = filename.toLowerCase().endsWith('.md')\n      ? filename.split('/').pop() || 'report.md'\n      : 'report.md';\n\n    const archived = await this.downloadMarkdownOrZip(\n      markdown,\n      filename,\n      mdEntryName,\n      options.signal,\n    );\n    return {\n      success: true,\n      format: 'markdown' as ExportFormat,\n      filename: archived.filename,\n      omittedImageCount: archived.omittedImageCount,\n    };\n  }\n\n  private static async exportDocumentPDF(\n    content: { markdown: string; html: string },\n    metadata: ConversationMetadata,\n    options: ExportOptions,\n  ): Promise<ExportResult> {\n    await DeepResearchPDFPrintService.export(\n      {\n        title: metadata.title || 'Deep Research Report',\n        url: metadata.url,\n        exportedAt: metadata.exportedAt,\n        markdown: content.markdown,\n        html: content.html,\n      },\n      { fontSize: options.fontSize },\n    );\n\n    return {\n      success: true,\n      format: 'pdf' as ExportFormat,\n      filename: options.filename || this.generateFilename('pdf', metadata.title, metadata.platform),\n    };\n  }\n\n  private static async exportDocumentImage(\n    content: { markdown: string; html: string },\n    metadata: ConversationMetadata,\n    options: ExportOptions,\n  ): Promise<ExportResult> {\n    const filename =\n      options.filename || this.generateFilename('png', metadata.title, metadata.platform);\n    await ImageExportService.exportDocument(\n      {\n        title: metadata.title || 'Deep Research Report',\n        url: metadata.url,\n        exportedAt: metadata.exportedAt,\n        markdown: content.markdown,\n        html: content.html,\n      },\n      {\n        filename,\n        fontSize: options.fontSize,\n        imageWidth: options.imageWidth,\n        signal: options.signal,\n      },\n    );\n\n    return {\n      success: true,\n      format: 'image' as ExportFormat,\n      filename,\n    };\n  }\n\n  private static extractDocumentContent(turns: ChatTurn[]): { markdown: string; html: string } {\n    const turn =\n      turns.find((item) => item.assistantContent || item.assistant.trim()) ||\n      turns.find((item) => item.userContent || item.user.trim());\n\n    if (!turn) {\n      return { markdown: '', html: '' };\n    }\n\n    if (turn.assistantContent) {\n      const extracted = turn.assistantContent;\n      return {\n        markdown: extracted.text || turn.assistant,\n        html: extracted.html || this.formatPlainTextAsHtml(extracted.text || turn.assistant),\n      };\n    }\n\n    if (turn.userContent) {\n      const extracted = turn.userContent;\n      return {\n        markdown: extracted.text || turn.user,\n        html: extracted.html || this.formatPlainTextAsHtml(extracted.text || turn.user),\n      };\n    }\n\n    const markdown = turn.assistant || turn.user || '';\n    return {\n      markdown,\n      html: this.formatPlainTextAsHtml(markdown),\n    };\n  }\n\n  private static composeDocumentMarkdown(content: string, metadata: ConversationMetadata): string {\n    const sections: string[] = [];\n    const title = metadata.title?.trim() || 'Deep Research Report';\n    const trimmedContent = content.trim() || '_No content_';\n    const startsWithHeading = this.hasLeadingMarkdownHeading(trimmedContent);\n\n    if (!startsWithHeading) {\n      sections.push(`# ${title}`);\n      sections.push('');\n    }\n\n    sections.push(trimmedContent);\n    sections.push('');\n    sections.push('---');\n    sections.push('');\n    sections.push(`Source: ${metadata.url}`);\n    sections.push(`Exported at: ${metadata.exportedAt}`);\n    return sections.join('\\n');\n  }\n\n  private static hasLeadingMarkdownHeading(content: string): boolean {\n    return /^#{1,6}\\s+\\S/m.test(content) && /^#{1,6}\\s+\\S/.test(content);\n  }\n\n  private static formatPlainTextAsHtml(content: string): string {\n    if (!content.trim()) return '';\n    const escaped = content.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');\n    return escaped\n      .split('\\n\\n')\n      .map((paragraph) => `<p>${paragraph.replace(/\\n/g, '<br>')}</p>`)\n      .join('\\n');\n  }\n\n  private static async downloadMarkdownOrZip(\n    markdown: string,\n    filename: string,\n    markdownEntryName: string,\n    signal?: AbortSignal,\n  ): Promise<{ filename: string; omittedImageCount: number }> {\n    this.assertNotAborted(signal);\n    const normalizedFilename = filename.toLowerCase().endsWith('.md') ? filename : `${filename}.md`;\n    if (MarkdownFormatter.extractImageUrls(markdown).length === 0) {\n      MarkdownFormatter.download(markdown, normalizedFilename);\n      return { filename: normalizedFilename, omittedImageCount: 0 };\n    }\n\n    return await packageMarkdownImages({\n      markdown,\n      normalizedFilename,\n      markdownEntryName,\n      signal,\n      fetchImage: (url, budget, fetchSignal) =>\n        this.fetchImageForMarkdownPackaging(url, budget, fetchSignal),\n      toOriginalSizeUrl: (url) => this.toOriginalSizeUrl(url),\n      pickExtension: (contentType, url) => this.pickImageExtension(contentType, url),\n    });\n  }\n\n  /**\n   * Replace Google image URL size parameter with =s0 for original resolution.\n   * Non-Google URLs are returned unchanged.\n   */\n  private static toOriginalSizeUrl(url: string): string {\n    const isGoogle = url.includes('googleusercontent.com') || url.includes('ggpht.com');\n    if (!isGoogle) return url;\n    const GOOGLE_SIZE_PATTERN = /=[swh]\\d+[^?#]*/;\n    if (GOOGLE_SIZE_PATTERN.test(url)) {\n      return url.replace(GOOGLE_SIZE_PATTERN, '=s0');\n    }\n    if (url.includes('?')) {\n      const parsed = new URL(url);\n      parsed.searchParams.set('s', '0');\n      return parsed.toString();\n    }\n    return url.split(/[?#]/, 1)[0].includes('=') ? url + '-s0' : url + '=s0';\n  }\n\n  private static pickImageExtension(contentType: string | null, url: string): string {\n    const byType: Record<string, string> = {\n      'image/png': 'png',\n      'image/jpeg': 'jpg',\n      'image/jpg': 'jpg',\n      'image/webp': 'webp',\n      'image/gif': 'gif',\n      'image/svg+xml': 'svg',\n    };\n    if (contentType && byType[contentType]) return byType[contentType];\n    const match = url.split('?')[0].match(/\\.(png|jpg|jpeg|gif|webp|svg)$/i);\n    if (match) return match[1].toLowerCase() === 'jpeg' ? 'jpg' : match[1].toLowerCase();\n    return 'bin';\n  }\n\n  private static async fetchImageForMarkdownPackaging(\n    url: string,\n    budget = { remainingBytes: MAX_EXPORT_IMAGE_TOTAL_BYTES },\n    signal?: AbortSignal,\n  ): Promise<{ blob: Blob; contentType: string | null } | null> {\n    return await fetchBoundedExportImage(url, budget, signal);\n  }\n\n  /**\n   * Download JSON file\n   */\n  private static downloadJSON(data: unknown, filename: string): void {\n    const blob = new Blob([JSON.stringify(data, null, 2)], {\n      type: 'application/json;charset=utf-8',\n    });\n    const url = URL.createObjectURL(blob);\n    const a = document.createElement('a');\n    a.href = url;\n    a.download = filename;\n    document.body.appendChild(a);\n    a.click();\n    setTimeout(() => {\n      try {\n        document.body.removeChild(a);\n      } catch {\n        /* ignore */\n      }\n      URL.revokeObjectURL(url);\n    }, 0);\n  }\n\n  /**\n   * Generate filename with timestamp\n   */\n  private static generateFilename(extension: string, title?: string, platform?: string): string {\n    const titlePart = this.sanitizeFilenamePart(title);\n    if (titlePart) {\n      return `${titlePart}.${extension}`;\n    }\n\n    const slug = (platform || 'gemini').toLowerCase().replace(/\\s+/g, '-');\n    const pad = (n: number) => String(n).padStart(2, '0');\n    const d = new Date();\n    const y = d.getFullYear();\n    const m = pad(d.getMonth() + 1);\n    const day = pad(d.getDate());\n    const hh = pad(d.getHours());\n    const mm = pad(d.getMinutes());\n    const ss = pad(d.getSeconds());\n    return `${slug}-chat-${y}${m}${day}-${hh}${mm}${ss}.${extension}`;\n  }\n\n  private static sanitizeFilenamePart(title?: string): string {\n    if (!title) return '';\n\n    const compact = title.trim().replace(/\\s+/g, ' ');\n    if (!compact) return '';\n\n    return compact\n      .replace(/[\\\\/:*?\"<>|]/g, '')\n      .replace(/\\s+/g, '-')\n      .replace(/\\.+$/g, '')\n      .slice(0, 80);\n  }\n\n  /**\n   * Get available export formats\n   */\n  static getAvailableFormats(): Array<{\n    format: ExportFormat;\n    label: string;\n    description: string;\n    recommended?: boolean;\n  }> {\n    return [\n      {\n        format: 'json' as ExportFormat,\n        label: 'JSON',\n        description: 'Machine-readable format for developers',\n      },\n      {\n        format: 'markdown' as ExportFormat,\n        label: 'Markdown',\n        description: 'Clean, portable text format (recommended)',\n        recommended: true,\n      },\n      {\n        format: 'pdf' as ExportFormat,\n        label: 'PDF',\n        description: 'Print-friendly format via Save as PDF',\n      },\n      {\n        format: 'image' as ExportFormat,\n        label: 'Image',\n        description: 'Single PNG image for sharing',\n      },\n    ];\n  }\n}\n"
    }
